with remaining_keys as (select id from shipments intersect all select id from shipments where carrier in ('UPS', 'Flash', 'DHL')), reconciled as (select s.* from shipments s inner join remaining_keys k on s.id = k.id) select case when cost >= 97 then 'LARGE' else 'SMALL' end as cost_tier, count(*) filter (where status = 'LOST') as lost_rows, round(sum(cost) / nullif(count(case when status = 'LOST' then 1 end), 0), 2) as cost_per_lost, sort_array(collect_set(carrier)) as carrier_list, approx_percentile(cost, array(0.25, 0.5, 0.75)) as cost_quartiles, sum(case when status = 'RETURNED' then cost else 0 end) as returned_cost, percentile_approx(cost, 0.95) as cost_p95 from reconciled group by 1 having round(sum(cost) / nullif(count(case when status = 'LOST' then 1 end), 0), 2) > 0 order by lost_rows desc nulls last
